import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Raggruppamenti possibili per polinomi a sei termini","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/a_algebra/ad/ad6fc.md","filePath":"lezioni/a_algebra/ad/ad6fc.md"}`),a={name:`lezioni/a_algebra/ad/ad6fc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="raggruppamenti-possibili-per-polinomi-a-sei-termini" tabindex="-1">Raggruppamenti possibili per polinomi a sei termini <a class="header-anchor" href="#raggruppamenti-possibili-per-polinomi-a-sei-termini" aria-label="Permalink to “Raggruppamenti possibili per polinomi a sei termini”">​</a></h1><p>In questo caso i raggruppamenti possibili sono ancor più numerosi: per dartene un&#39;idea pensa a tutte le scomposizioni fatte tali che il numero dei termini di due scomposizioni sia <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>6</mn></mrow><annotation encoding="application/x-tex">6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span> e tali che i termini delle due scomposizioni non si possano sommare tra loro; quindi:</p><ul><li>differenza fra due quadrati di un binomio</li><li>cubo di un binomio con un raccoglimento fra due termini</li><li>due termini come differenza di quadrati e gli altri con un raccoglimento parziale</li><li>quattro termini come raggruppamento a differenza di quadrati e gli altri due come raccoglimento</li></ul><p>E ve ne sono parecchie altre se consideriamo per due termini la somma o la differenza di potenze dispari e la differenza di potenze pari. Se poi facciamo intervenire la scomposizione di Ruffini il numero aumenta di parecchio, quindi, senza dilungarci troppo, anche perché questo è un argomento piuttosto secondario, concludiamo le scomposizioni passando alla <a href="./ad6g.html">tabella di riepilogo</a></p>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};